interface InaLogoProps {
  height?: number;
  variant?: 'original' | 'white' | 'accent';
}

export function InaLogo({ height = 38, variant = 'original' }: InaLogoProps) {
  const width = Math.round(height * (706.14 / 388.86));
  
  let processedSvg = rawSvg;
  if (variant === 'white') {
    processedSvg = rawSvg
      .replace(/#526635/g, '#ffffff')
      .replace(/#8d9f6f/g, '#c9f36b');
  } else if (variant === 'accent') {
    processedSvg = rawSvg
      .replace(/#526635/g, '#c9f36b')
      .replace(/#8d9f6f/g, '#ffffff');
  }

  return (
    <View style={{ width, height }}>
      <SvgXml xml={processedSvg} width={width} height={height} />
    </View>
  );
}
